-- Seed verification: any row returned rejects the seed. Run after every `task seed`.
-- Q1: orphan edges. Q2: orphan evidence. Q3: confirmed claims without a source.
SELECT 'orphan_edge' AS chk, id FROM band_members WHERE band_id NOT IN (SELECT id FROM bands) OR member_id NOT IN (SELECT id FROM members) UNION ALL SELECT 'orphan_edge', id FROM releases WHERE band_id NOT IN (SELECT id FROM bands) UNION ALL SELECT 'orphan_edge', id FROM media_links WHERE (release_id IS NULL) = (band_id IS NULL) OR (release_id NOT IN (SELECT id FROM releases)) OR (band_id NOT IN (SELECT id FROM bands));
SELECT 'orphan_evidence' AS chk, id FROM claim_sources WHERE entity_id NOT IN (SELECT id FROM bands UNION ALL SELECT id FROM members UNION ALL SELECT id FROM band_members UNION ALL SELECT id FROM releases UNION ALL SELECT id FROM media_links);
SELECT 'unsourced_confirmed' AS chk, id FROM claim_sources WHERE status='confirmed' AND (source_url IS NULL OR source_url='' OR accessed_at IS NULL OR accessed_at='');
